1	<!DOCTYPE html>
2	<html lang="en" data-theme="dark">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
6	  <title>Project Entry</title>
7	  <link rel="preconnect" href="https://fonts.googleapis.com">
8	  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
9	  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap">
10	
11	  <style>
12	    /* ========================================================================
13	       DESIGN SYSTEM: BIGGER UI FOR 100% ZOOM COMFORT
14	       Scaled up base sizes so normal viewing doesn't require zoom
15	       ======================================================================== */
16	
17	    :root {
18	      /* Colors */
19	      --bg-canvas: #0a0908;
20	      --bg-card: #15110d;
21	      --bg-card-hover: #1f1813;
22	      --bg-input: #1c1611;
23	      --bg-input-focus: #28201a;
24	      --text-primary: #fefdfb;
25	      --text-secondary: #e8ddd0;
26	      --text-tertiary: #8f7f6e;
27	      --text-dim: #6a5d4f;
28	      --border-light: #3a2d23;
29	      --border-mid: #4d3d30;
30	      --accent: #ff9e1b;
31	      --accent-hover: #ffb03a;
32	      --accent-glow: rgba(255, 158, 27, 0.3);
33	      --accent-bg: rgba(255, 158, 27, 0.15);
34	
35	      /* Semantic colors */
36	      --success: #10b981;
37	      --warning: #f59e0b;
38	      --danger: #f43f5e;
39	
40	      /* Typography - BIGGER BASE */
41	      --font-display: "IBM Plex Sans", system-ui, sans-serif;
42	      --font-body: "IBM Plex Sans", system-ui, sans-serif;
43	      --font-mono: "IBM Plex Mono", monospace;
44	      --base-font-size: 18px;
45	
46	      /* Spacing - LARGER GAPS */
47	      --gap-xs: 0.75rem;
48	      --gap-sm: 1rem;
49	      --gap-md: 1.5rem;
50	      --gap-lg: 2rem;
51	      --gap-xl: 3rem;
52	
53	      /* Sizing - BIGGER RADIUS */
54	      --radius-sm: 8px;
55	      --radius-md: 10px;
56	      --radius-lg: 12px;
57	
58	      /* Inputs - MUCH BIGGER */
59	      --input-height: 56px;
60	      --input-padding: 0 1.25rem;
61	
62	      color-scheme: dark;
63	    }
64	
65	    @media (prefers-color-scheme: light) {
66	      :root:not([data-theme="dark"]) {
67	        --bg-canvas: #faf8f5;
68	        --bg-card: #fff8f3;
69	        --bg-card-hover: #fff0e8;
70	        --bg-input: #f5ede5;
71	        --bg-input-focus: #fff8f3;
72	        --text-primary: #18130e;
73	        --text-secondary: #382f26;
74	        --text-tertiary: #6b5a49;
75	        --text-dim: #9e8c79;
76	        --border-light: #e8dccf;
77	        --border-mid: #d9cabc;
78	        --accent: #d97706;
79	        --accent-hover: #b45309;
80	        --accent-bg: rgba(217, 119, 6, 0.12);
81	        color-scheme: light;
82	      }
83	    }
84	
85	    :root[data-theme="light"] {
86	      --bg-canvas: #faf8f5;
87	      --bg-card: #fff8f3;
88	      --bg-card-hover: #fff0e8;
89	      --bg-input: #f5ede5;
90	      --bg-input-focus: #fff8f3;
91	      --text-primary: #18130e;
92	      --text-secondary: #382f26;
93	      --text-tertiary: #6b5a49;
94	      --text-dim: #9e8c79;
95	      --border-light: #e8dccf;
96	      --border-mid: #d9cabc;
97	      --accent: #d97706;
98	      --accent-hover: #b45309;
99	      --accent-bg: rgba(217, 119, 6, 0.12);
100	      color-scheme: light;
101	    }
102	
103	    * {
104	      box-sizing: border-box;
105	      margin: 0;
106	      padding: 0;
107	    }
108	
109	    html, body {
110	      height: 100%;
111	    }
112	
113	    body {
114	      background: var(--bg-canvas);
115	      color: var(--text-secondary);
116	      font: var(--base-font-size) var(--font-body);
117	      line-height: 1.6;
118	      padding: 3rem 2rem 5rem;
119	      display: flex;
120	      justify-content: center;
121	    }
122	
123	    .app-container {
124	      width: 100%;
125	      max-width: 1400px;
126	      display: flex;
127	      flex-direction: column;
128	      gap: var(--gap-xl);
129	    }
130	
131	    /* ========================================================================
132	       HEADER & NAVIGATION
133	       ======================================================================== */
134	
135	    .header {
136	      display: flex;
137	      flex-direction: column;
138	      gap: var(--gap-md);
139	      padding-bottom: var(--gap-lg);
140	      border-bottom: 1px solid var(--border-light);
141	    }
142	
143	    .header-top {
144	      display: flex;
145	      justify-content: space-between;
146	      align-items: flex-start;
147	      gap: var(--gap-md);
148	      flex-wrap: wrap;
149	    }
150	
151	    h1 {
152	      font: 700 2.5rem var(--font-display);
153	      color: var(--text-primary);
154	      margin: 0;
155	      display: flex;
156	      align-items: center;
157	      gap: 1rem;
158	    }
159	
160	    .badge {
161	      font: 600 0.85rem var(--font-mono);
162	      color: var(--accent);
163	      background: var(--accent-bg);
164	      border: 1px solid var(--accent);
165	      padding: 0.5rem 0.9rem;
166	      border-radius: var(--radius-sm);
167	      text-transform: uppercase;
168	      letter-spacing: 0.05em;
169	    }
170	
171	    .header-subtitle {
172	      font: 16px var(--font-body);
173	      color: var(--text-tertiary);
174	      max-width: 600px;
175	    }
176	
177	    .header-actions {
178	      display: flex;
179	      gap: var(--gap-sm);
180	      flex-wrap: wrap;
181	    }
182	
183	    /* ========================================================================
184	       BUTTONS & CONTROLS
185	       ======================================================================== */
186	
187	    button {
188	      font: inherit;
189	      cursor: pointer;
190	      border: none;
191	      outline: none;
192	      transition: all 0.15s ease;
193	      border-radius: var(--radius-md);
194	    }
195	
196	    .btn {
197	      height: 52px;
198	      padding: 0 1.5rem;
199	      font-weight: 600;
200	      font-size: 16px;
201	      display: inline-flex;
202	      align-items: center;
203	      gap: 0.75rem;
204	      background: var(--bg-card);
205	      border: 1px solid var(--border-light);
206	      color: var(--text-secondary);
207	    }
208	
209	    .btn:hover {
210	      background: var(--bg-card-hover);
211	      border-color: var(--border-mid);
212	      color: var(--text-primary);
213	    }
214	
215	    .btn.primary {
216	      background: var(--accent);
217	      border-color: var(--accent);
218	      color: #0a0908;
219	      font-weight: 700;
220	    }
221	
222	    .btn.primary:hover {
223	      background: var(--accent-hover);
224	      border-color: var(--accent-hover);
225	    }
226	
227	    .btn.small {
228	      height: 42px;
229	      padding: 0 1rem;
230	      font-size: 14px;
231	    }
232	
233	    .btn.icon-only {
234	      width: 52px;
235	      padding: 0;
236	      justify-content: center;
237	    }
238	
239	    /* Navigation tabs */
240	    .nav-tabs {
241	      display: flex;
242	      gap: var(--gap-xs);
243	      flex-wrap: wrap;
244	      background: var(--bg-card);
245	      border: 1px solid var(--border-light);
246	      padding: var(--gap-sm);
247	      border-radius: var(--radius-md);
248	    }
249	
250	    .tab-btn {
251	      padding: 0.8rem 1.2rem;
252	      font-weight: 600;
253	      font-size: 15px;
254	      background: transparent;
255	      border: none;
256	      color: var(--text-tertiary);
257	      border-radius: var(--radius-sm);
258	    }
259	
260	    .tab-btn:hover {
261	      background: var(--bg-input);
262	      color: var(--text-secondary);
263	    }
264	
265	    .tab-btn.active {
266	      background: var(--accent-bg);
267	      color: var(--accent);
268	      border: 1px solid var(--accent);
269	    }
270	
271	    /* ========================================================================
272	       CARDS & SECTIONS
273	       ======================================================================== */
274	
275	    .card {
276	      background: var(--bg-card);
277	      border: 1px solid var(--border-light);
278	      border-radius: var(--radius-lg);
279	      overflow: hidden;
280	      transition: border-color 0.15s ease;
281	    }
282	
283	    .card:hover {
284	      border-color: var(--border-mid);
285	    }
286	
287	    .card-header {
288	      padding: var(--gap-md);
289	      background: rgba(255, 255, 255, 0.02);
290	      border-bottom: 1px solid var(--border-light);
291	      display: flex;
292	      justify-content: space-between;
293	      align-items: center;
294	      gap: var(--gap-md);
295	    }
296	
297	    .card-title {
298	      font-weight: 700;
299	      color: var(--text-primary);
300	      font-size: 17px;
301	      display: flex;
302	      align-items: center;
303	      gap: 0.75rem;
304	    }
305	
306	    .card-body {
307	      padding: var(--gap-md);
308	      display: flex;
309	      flex-direction: column;
310	      gap: var(--gap-lg);
311	    }
312	
313	    /* ========================================================================
314	       FORMS & INPUTS
315	       ======================================================================== */
316	
317	    .field-group {
318	      display: flex;
319	      flex-direction: column;
320	      gap: var(--gap-sm);
321	    }
322	
323	    .field-label {
324	      font-weight: 600;
325	      font-size: 15px;
326	      color: var(--text-tertiary);
327	      text-transform: uppercase;
328	      letter-spacing: 0.04em;
329	      display: flex;
330	      justify-content: space-between;
331	      align-items: center;
332	    }
333	
334	    .field-hint {
335	      font-size: 14px;
336	      color: var(--text-dim);
337	      font-family: var(--font-mono);
338	      font-weight: 400;
339	      text-transform: none;
340	      letter-spacing: normal;
341	    }
342	
343	    /* INPUT SIZING: 56px height for comfortable clicking */
344	    input[type="text"],
345	    input[type="email"],
346	    input[type="number"],
347	    select,
348	    textarea {
349	      height: var(--input-height);
350	      padding: var(--input-padding);
351	      background: var(--bg-input);
352	      border: 1px solid var(--border-light);
353	      border-radius: var(--radius-md);
354	      color: var(--text-primary);
355	      font-family: var(--font-body);
356	      font-size: 16px;
357	      transition: all 0.15s ease;
358	      resize: none;
359	    }
360	
361	    input[type="text"]:focus,
362	    input[type="email"]:focus,
363	    input[type="number"]:focus,
364	    select:focus,
365	    textarea:focus {
366	      background: var(--bg-input-focus);
367	      border-color: var(--accent);
368	      box-shadow: 0 0 0 4px var(--accent-glow);
369	      outline: none;
370	    }
371	
372	    textarea {
373	      height: 120px;
374	      padding: var(--gap-sm);
375	      line-height: 1.6;
376	      font-size: 14px;
377	    }
378	
379	    select {
380	      appearance: none;
381	      background-image: url("data:image/svg+xml,%3Csvg width='8' height='6' viewBox='0 0 8 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L4 4L7 1' stroke='%23ff9e1b' stroke-width='1.2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
382	      background-repeat: no-repeat;
383	      background-position: right 12px center;
384	      padding-right: 2.5rem;
385	      cursor: pointer;
386	    }
387	
388	    /* ========================================================================
389	       LAYOUT GRID
390	       ======================================================================== */
391	
392	    .workspace {
393	      display: grid;
394	      grid-template-columns: 1fr 380px;
395	      gap: var(--gap-xl);
396	      align-items: start;
397	    }
398	
399	    @media (max-width: 1024px) {
400	      .workspace {
401	        grid-template-columns: 1fr;
402	      }
403	    }
404	
405	    .columns-list {
406	      display: flex;
407	      flex-direction: column;
408	      gap: 2.5rem;
409	    }
410	
411	    /* ========================================================================
412	       COLUMN CARDS
413	       ======================================================================== */
414	
415	    .column-card {
416	      border-left: 4px solid var(--accent);
417	      transition: all 0.2s ease;
418	    }
419	
420	    .column-card.pk { border-left-color: #38bdf8; }
421	    .column-card.text { border-left-color: #10b981; }
422	    .column-card.scalar { border-left-color: #f59e0b; }
423	    .column-card.enum { border-left-color: #f43f5e; }
424	    .column-card.rel { border-left-color: #ff9e1b; }
425	
426	    .column-card-header {
427	      padding: var(--gap-md);
428	      background: rgba(255, 255, 255, 0.015);
429	      border-bottom: 1px solid var(--border-light);
430	      display: flex;
431	      justify-content: space-between;
432	      align-items: center;
433	      gap: var(--gap-md);
434	      cursor: pointer;
435	      user-select: none;
436	    }
437	
438	    .column-card.collapsed .column-card-body {
439	      display: none;
440	    }
441	
442	    .column-chevron {
443	      display: inline-flex;
444	      align-items: center;
445	      justify-content: center;
446	      width: 24px;
447	      height: 24px;
448	      transition: transform 0.2s ease;
449	      color: var(--text-tertiary);
450	      flex-shrink: 0;
451	    }
452	
453	    .column-card.collapsed .column-chevron {
454	      transform: rotate(-90deg);
455	    }
456	
457	    .column-controls {
458	      display: flex;
459	      gap: 0.3rem;
460	      align-items: center;
461	    }
462	
463	    .column-reorder {
464	      display: flex;
465	      gap: 0.2rem;
466	      padding: 0.3rem;
467	      background: var(--bg-input);
468	      border: 1px solid var(--border-light);
469	      border-radius: 4px;
470	    }
471	
472	    .reorder-btn {
473	      width: 28px;
474	      height: 28px;
475	      padding: 0;
476	      background: transparent;
477	      border: none;
478	      color: var(--text-tertiary);
479	      cursor: pointer;
480	      display: flex;
481	      align-items: center;
482	      justify-content: center;
483	      font-size: 14px;
484	      border-radius: 3px;
485	      transition: all 0.15s ease;
486	    }
487	
488	    .reorder-btn:hover {
489	      background: var(--bg-card-hover);
490	      color: var(--accent);
491	    }
492	
493	    .reorder-btn:disabled {
494	      opacity: 0.4;
495	      cursor: not-allowed;
496	    }
497	
498	    .column-card-title {
499	      display: flex;
500	      align-items: center;
501	      gap: 0.5rem;
502	      flex: 1;
503	      min-width: 0;
504	    }
505	
506	    .column-icon {
507	      font-size: 18px;
508	      flex-shrink: 0;
509	    }
510	
511	    .column-number {
512	      font-family: var(--font-mono);
513	      font-size: 12px;
514	      color: var(--text-dim);
515	      min-width: 24px;
516	    }
517	
518	    .column-name {
519	      font: 600 14px var(--font-body);
520	      color: var(--text-primary);
521	      word-break: break-word;
522	    }
523	
524	    .column-tag {
525	      font: 600 11px var(--font-mono);
526	      color: var(--accent);
527	      background: var(--accent-bg);
528	      border: 1px solid var(--accent);
529	      padding: 0.25rem 0.6rem;
530	      border-radius: var(--radius-sm);
531	      text-transform: uppercase;
532	      letter-spacing: 0.03em;
533	      white-space: nowrap;
534	      flex-shrink: 0;
535	    }
536	
537	    .column-card-body {
538	      padding: var(--gap-md);
539	      display: flex;
540	      flex-direction: column;
541	      gap: var(--gap-lg);
542	    }
543	
544	    .field-grid-2 {
545	      display: grid;
546	      grid-template-columns: 1fr 1fr;
547	      gap: var(--gap-md);
548	    }
549	
550	    @media (max-width: 640px) {
551	      .field-grid-2 {
552	        grid-template-columns: 1fr;
553	      }
554	    }
555	
556	    /* ========================================================================
557	       QUICK ADD SECTION
558	       ======================================================================== */
559	
560	    .quick-add {
561	      background: var(--bg-card);
562	      border: 2px dashed var(--border-mid);
563	      border-radius: var(--radius-lg);
564	      padding: var(--gap-lg);
565	      display: flex;
566	      flex-direction: column;
567	      gap: var(--gap-md);
568	    }
569	
570	    .quick-add-title {
571	      font: 600 13px var(--font-body);
572	      color: var(--text-tertiary);
573	      text-transform: uppercase;
574	      letter-spacing: 0.05em;
575	    }
576	
577	    .quick-add-grid {
578	      display: grid;
579	      grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
580	      gap: var(--gap-md);
581	    }
582	
583	    .quick-add-btn {
584	      padding: var(--gap-sm);
585	      background: var(--bg-input);
586	      border: 1px solid var(--border-light);
587	      border-radius: var(--radius-md);
588	      color: var(--text-secondary);
589	      display: flex;
590	      flex-direction: column;
591	      gap: 0.3rem;
592	      text-align: left;
593	      transition: all 0.15s ease;
594	      cursor: pointer;
595	      min-height: 72px;
596	      justify-content: flex-start;
597	    }
598	
599	    .quick-add-btn:hover {
600	      background: var(--bg-card-hover);
601	      border-color: var(--accent);
602	      transform: translateY(-2px);
603	    }
604	
605	    .qa-slug {
606	      font: 600 11px var(--font-mono);
607	      color: var(--accent);
608	    }
609	
610	    .qa-desc {
611	      font: 12px var(--font-body);
612	      color: var(--text-dim);
613	    }
614	
615	    /* ========================================================================
616	       INSPECTOR PANEL
617	       ======================================================================== */
618	
619	    .inspector {
620	      position: sticky;
621	      top: 2rem;
622	      display: flex;
623	      flex-direction: column;
624	      gap: var(--gap-md);
625	    }
626	
627	    .inspector-tabs {
628	      display: flex;
629	      gap: var(--gap-xs);
630	      background: var(--bg-card);
631	      border: 1px solid var(--border-light);
632	      padding: var(--gap-xs);
633	      border-radius: var(--radius-md);
634	    }
635	
636	    .inspector-tab-btn {
637	      flex: 1;
638	      padding: 0.5rem;
639	      font: 600 11px var(--font-mono);
640	      color: var(--text-tertiary);
641	      background: transparent;
642	      border: none;
643	      border-radius: var(--radius-sm);
644	      text-transform: uppercase;
645	      text-align: center;
646	      transition: all 0.15s ease;
647	    }
648	
649	    .inspector-tab-btn:hover {
650	      background: var(--bg-input);
651	      color: var(--text-secondary);
652	    }
653	
654	    .inspector-tab-btn.active {
655	      background: var(--accent-bg);
656	      color: var(--accent);
657	      border: 1px solid var(--accent);
658	    }
659	
660	    .code-view {
661	      background: var(--bg-card);
662	      border: 1px solid var(--border-light);
663	      border-radius: var(--radius-lg);
664	      overflow: hidden;
665	      display: flex;
666	      flex-direction: column;
667	    }
668	
669	    .code-header {
670	      padding: var(--gap-md);
671	      background: rgba(255, 255, 255, 0.02);
672	      border-bottom: 1px solid var(--border-light);
673	      font: 600 12px var(--font-mono);
674	      color: var(--text-dim);
675	      text-transform: uppercase;
676	      display: flex;
677	      justify-content: space-between;
678	      align-items: center;
679	    }
680	
681	    .code-pre {
682	      padding: var(--gap-md);
683	      font-family: var(--font-mono);
684	      font-size: 12px;
685	      line-height: 1.5;
686	      color: var(--text-secondary);
687	      overflow-x: auto;
688	      max-height: 400px;
689	      overflow-y: auto;
690	      white-space: pre;
691	    }
692	
693	    /* ========================================================================
694	       FILTER BAR
695	       ======================================================================== */
696	
697	    .filter-bar {
698	      display: flex;
699	      gap: var(--gap-sm);
700	      flex-wrap: wrap;
701	      margin-bottom: var(--gap-md);
702	    }
703	
704	    .filter-btn {
705	      padding: 0.5rem 1rem;
706	      font: 600 13px var(--font-body);
707	      background: var(--bg-card);
708	      border: 1px solid var(--border-light);
709	      border-radius: var(--radius-sm);
710	      color: var(--text-tertiary);
711	      cursor: pointer;
712	      transition: all 0.15s ease;
713	    }
714	
715	    .filter-btn:hover {
716	      background: var(--bg-card-hover);
717	      color: var(--text-secondary);
718	    }
719	
720	    .filter-btn.active {
