925	  <script>
926	    /* ========================================================================
927	       STANDALONE TABLE SCHEMA EDITOR — EMBEDDED MOCK DATA
928	       ======================================================================== */
929	
930	    const FIELD_TYPES = {
931	      hex_id: { category: 'pk', icon: '🔑', title: 'Hex ID', sql: 'TEXT PRIMARY KEY' },
932	      text_single: { category: 'text', icon: '📝', title: 'Text (single)', sql: 'TEXT' },
933	      text_multi: { category: 'text', icon: '📝', title: 'Text (multi)', sql: 'TEXT' },
934	      int_scalar: { category: 'scalar', icon: '🔢', title: 'Integer', sql: 'INTEGER' },
935	      float_scalar: { category: 'scalar', icon: '🔢', title: 'Float', sql: 'REAL' },
936	      boolean: { category: 'boolean', icon: '🔘', title: 'Boolean', sql: 'INTEGER DEFAULT 0' },
937	      enum_single: { category: 'enum', icon: '🏷️', title: 'Enum (single)', sql: 'TEXT' },
938	      enum_multi: { category: 'enum', icon: '🏷️', title: 'Enum (multi)', sql: 'TEXT (JSON)' },
939	      relation_single: { category: 'rel', icon: '🔗', title: 'Relation (single)', sql: 'TEXT' },
940	      relation_multi: { category: 'rel', icon: '🔗', title: 'Relation (multi)', sql: 'TEXT (JSON)' }
941	    };
942	
943	    const MOCK_DATA = {
944	      users: {
945	        table_name: 'users',
946	        columns: [
947	          { name: 'User ID', slug: 'id', type: 'hex_id', metadata: { prefix: 'USER' } },
948	          { name: 'Username', slug: 'username', type: 'text_single', metadata: {} },
949	          { name: 'Email', slug: 'email', type: 'text_single', metadata: {} },
950	          { name: 'Bio', slug: 'bio', type: 'text_multi', metadata: {} },
951	          { name: 'Age', slug: 'age', type: 'int_scalar', metadata: {} },
952	          { name: 'Balance', slug: 'balance', type: 'float_scalar', metadata: {} },
953	          { name: 'Active', slug: 'is_active', type: 'boolean', metadata: {} },
954	          { name: 'Role', slug: 'role', type: 'enum_single', metadata: { options: ['admin', 'editor', 'viewer'] } },
955	          { name: 'Tags', slug: 'tags', type: 'enum_multi', metadata: { options: ['premium', 'verified', 'staff'] } },
956	          { name: 'Manager', slug: 'manager_id', type: 'relation_single', metadata: { target: 'users' } },
957	          { name: 'Projects', slug: 'project_ids', type: 'relation_multi', metadata: { target: 'projects' } }
958	        ]
959	      },
960	      projects: {
961	        table_name: 'projects',
962	        columns: [
963	          { name: 'Project ID', slug: 'id', type: 'hex_id', metadata: { prefix: 'PROJ' } },
964	          { name: 'Title', slug: 'title', type: 'text_single', metadata: {} },
965	          { name: 'Description', slug: 'description', type: 'text_multi', metadata: {} },
966	          { name: 'Budget', slug: 'budget', type: 'float_scalar', metadata: {} },
967	          { name: 'Status', slug: 'status', type: 'enum_single', metadata: { options: ['planning', 'active', 'completed'] } },
968	          { name: 'Public', slug: 'is_public', type: 'boolean', metadata: {} },
969	          { name: 'Owner', slug: 'owner_id', type: 'relation_single', metadata: { target: 'users' } },
970	          { name: 'Team Members', slug: 'member_ids', type: 'relation_multi', metadata: { target: 'users' } }
971	        ]
972	      }
973	    };
974	
975	    let tables = JSON.parse(JSON.stringify(MOCK_DATA));
976	    let activeTable = 'users';
977	    let activeTab = 'sql';
978	    let activeFilter = 'all';
979	    let collapsedColumns = new Set(); // Track which columns are collapsed
980	
981	    function init() {
982	      renderTableTabs();
983	      renderColumns();
984	      renderFilters();
985	      updateInspector();
986	    }
987	
988	    function toggleColumnCollapse(idx) {
989	      const colId = `col-${idx}`;
990	      const card = document.getElementById(colId);
991	      if (!card) return;
992	
993	      if (collapsedColumns.has(idx)) {
994	        collapsedColumns.delete(idx);
995	        card.classList.remove('collapsed');
996	      } else {
997	        collapsedColumns.add(idx);
998	        card.classList.add('collapsed');
999	      }
1000	    }
1001	
1002	    function renderTableTabs() {
1003	      const container = document.getElementById('table-tabs');
1004	      const names = Object.keys(tables);
1005	      container.innerHTML = names.map(name => `
1006	        <button class="tab-btn ${name === activeTable ? 'active' : ''}" onclick="switchTable('${name}')">
1007	          📁 ${name}
1008	        </button>
1009	      `).join('') + `
1010	        <button class="tab-btn" onclick="createTable()" style="border-style: dashed; border-color: var(--border-mid);">
1011	          + New Table
1012	        </button>
1013	      `;
1014	    }
1015	
1016	    function switchTable(name) {
1017	      if (!tables[name]) return;
1018	      activeTable = name;
1019	      document.getElementById('active-table-name').textContent = name;
1020	      document.getElementById('table-name-input').value = name;
1021	      renderTableTabs();
1022	      renderColumns();
1023	      updateInspector();
1024	    }
1025	
1026	    function createTable() {
1027	      const name = prompt('Table name (e.g., tasks, inventory):');
1028	      if (!name) return;
1029	      const clean = name.toLowerCase().replace(/[^a-z0-9_]/g, '_');
1030	      if (tables[clean]) {
1031	        alert('Table already exists');
1032	        return;
1033	      }
1034	      tables[clean] = {
1035	        table_name: clean,
1036	        columns: [{ name: 'ID', slug: 'id', type: 'hex_id', metadata: { prefix: clean.substring(0, 4).toUpperCase() } }]
1037	      };
1038	      switchTable(clean);
1039	      showToast(`Created table "${clean}"`);
1040	    }
1041	
1042	    function renderFilters() {
1043	      const bar = document.getElementById('filter-bar');
1044	      const categories = ['all', 'pk', 'text', 'scalar', 'boolean', 'enum', 'rel'];
1045	      const icons = { all: '📊', pk: '🔑', text: '📝', scalar: '🔢', boolean: '🔘', enum: '🏷️', rel: '🔗' };
1046	      bar.innerHTML = categories.map(cat => `
1047	        <button class="filter-btn ${cat === activeFilter ? 'active' : ''}" onclick="setFilter('${cat}')">
1048	          ${icons[cat]} ${cat === 'all' ? 'All' : cat.charAt(0).toUpperCase() + cat.slice(1)}
1049	        </button>
1050	      `).join('');
1051	    }
1052	
1053	    function setFilter(cat) {
1054	      activeFilter = cat;
1055	      renderFilters();
1056	      renderColumns();
1057	    }
1058	
1059	    function renderColumns() {
1060	      if (!tables[activeTable]) return;
1061	      const table = tables[activeTable];
1062	      const stream = document.getElementById('columns-stream');
1063	
1064	      const columnCount = table.columns.length;
1065	      document.getElementById('columns-count').textContent = `${columnCount} column${columnCount !== 1 ? 's' : ''}`;
1066	
1067	      const filtered = activeFilter === 'all'
1068	        ? table.columns
1069	        : table.columns.filter(col => FIELD_TYPES[col.type]?.category === activeFilter);
1070	
1071	      if (filtered.length === 0) {
1072	        stream.innerHTML = '<div style="padding: 3rem 1.5rem; text-align: center; color: var(--text-dim);">No columns in this category</div>';
1073	        return;
1074	      }
1075	
1076	      stream.innerHTML = filtered.map((col, idx) => renderColumnCard(col, idx)).join('');
1077	    }
1078	
1079	    function renderColumnCard(col, idx) {
1080	      const type = FIELD_TYPES[col.type];
1081	      const table = tables[activeTable];
1082	      const isFirst = idx === 0;
1083	      const isLast = idx === table.columns.length - 1;
1084	
1085	      return `
1086	        <section class="card column-card ${type.category} ${collapsedColumns.has(idx) ? 'collapsed' : ''}" id="col-${idx}">
1087	          <div class="column-card-header" onclick="toggleColumnCollapse(${idx})">
1088	            <div style="display: flex; align-items: center; gap: 0.5rem; flex: 1; min-width: 0;">
1089	              <span class="column-chevron">${collapsedColumns.has(idx) ? '▶' : '▼'}</span>
1090	              <div class="column-card-title">
1091	                <span class="column-icon">${type.icon}</span>
1092	                <span class="column-number">#${idx + 1}</span>
1093	                <span class="column-name">${col.name}</span>
1094	              </div>
1095	            </div>
1096	            <div class="column-controls" onclick="event.stopPropagation()">
1097	              <div class="column-reorder">
1098	                <button class="reorder-btn" onclick="moveColumn(${idx}, -1)" ${isFirst ? 'disabled' : ''} title="Move Up">▲</button>
1099	                <button class="reorder-btn" onclick="moveColumn(${idx}, 1)" ${isLast ? 'disabled' : ''} title="Move Down">▼</button>
1100	              </div>
1101	              <span class="column-tag">${type.title}</span>
1102	              <button class="btn small icon-only" onclick="deleteColumn(${idx})" title="Delete">✕</button>
1103	            </div>
1104	          </div>
1105	          <div class="column-card-body">
1106	            <div class="field-grid-2">
1107	              <div class="field-group">
1108	                <label class="field-label">Column Name</label>
1109	                <input type="text" value="${col.name}" onchange="updateColumnName(${idx}, this.value)">
1110	              </div>
1111	              <div class="field-group">
1112	                <label class="field-label">Column Type</label>
1113	                <select onchange="updateColumnType(${idx}, this.value)">
1114	                  ${Object.entries(FIELD_TYPES).map(([slug, info]) => `
1115	                    <option value="${slug}" ${col.type === slug ? 'selected' : ''}>
1116	                      ${info.icon} ${info.title}
1117	                    </option>
1118	                  `).join('')}
1119	                </select>
1120	              </div>
1121	            </div>
1122	            ${renderMetadata(col, idx)}
1123	          </div>
1124	        </section>
1125	      `;
1126	    }
1127	
1128	    function renderMetadata(col, idx) {
1129	      const meta = col.metadata || {};
1130	      if (col.type === 'hex_id') {
1131	        return `
1132	          <div class="field-group">
1133	            <label class="field-label">ID Prefix (4 chars)</label>
1134	            <input type="text" maxlength="4" value="${meta.prefix || ''}"
1135	              onchange="updateMeta(${idx}, 'prefix', this.value)">
1136	          </div>
1137	        `;
1138	      }
1139	      if (col.type.startsWith('enum_')) {
1140	        const options = Array.isArray(meta.options) ? meta.options : [];
1141	        return `
1142	          <div class="field-group">
1143	            <label class="field-label">Options</label>
1144	            <div style="display: flex; flex-wrap: wrap; gap: 0.5rem;">
1145	              ${options.map((opt, i) => `
1146	                <span style="background: var(--accent-bg); color: var(--accent); padding: 0.4rem 0.8rem; border-radius: 4px; font-size: 13px; display: flex; gap: 0.5rem; align-items: center;">
1147	                  ${opt}
1148	                  <button onclick="removeOption(${idx}, ${i})" style="background: none; border: none; cursor: pointer; color: var(--accent); padding: 0;">✕</button>
1149	                </span>
1150	              `).join('')}
1151	            </div>
1152	            <input type="text" placeholder="Add option, press Enter"
1153	              onkeydown="if(event.key==='Enter'){addOption(${idx}, this.value); this.value='';}">
1154	          </div>
1155	        `;
1156	      }
1157	      if (col.type.startsWith('relation_')) {
1158	        const target = meta.target || 'self';
1159	        return `
1160	          <div class="field-group">
1161	            <label class="field-label">Target Table</label>
1162	            <select onchange="updateMeta(${idx}, 'target', this.value)">
1163	              <option value="self" ${target === 'self' ? 'selected' : ''}>Self (tree)</option>
1164	              ${Object.keys(tables).map(t => `
1165	                <option value="${t}" ${target === t ? 'selected' : ''}>${t}</option>
1166	              `).join('')}
1167	            </select>
1168	          </div>
1169	        `;
1170	      }
1171	      return '';
1172	    }
1173	
1174	    function addField(type) {
1175	      const table = tables[activeTable];
1176	      const newCol = {
1177	        name: FIELD_TYPES[type].title,
1178	        slug: 'new_field',
1179	        type: type,
1180	        metadata: {}
1181	      };
1182	      if (type.startsWith('enum_')) newCol.metadata.options = ['option1', 'option2'];
1183	      if (type.startsWith('relation_')) newCol.metadata.target = 'self';
1184	      if (type === 'hex_id') newCol.metadata.prefix = activeTable.substring(0, 4).toUpperCase();
1185	      table.columns.push(newCol);
1186	      renderColumns();
1187	      updateInspector();
1188	      showToast(`Added ${FIELD_TYPES[type].title}`);
1189	    }
1190	
1191	    function deleteColumn(idx) {
1192	      const name = tables[activeTable].columns[idx].name;
1193	      tables[activeTable].columns.splice(idx, 1);
1194	      // Also remove collapsed state for this index and shift higher indices down
1195	      if (collapsedColumns.has(idx)) {
1196	        collapsedColumns.delete(idx);
1197	      }
1198	      // Shift collapsed indices > idx down by 1
1199	      const newCollapsed = new Set();
1200	      for (const c of collapsedColumns) {
1201	        if (c > idx) {
1202	          newCollapsed.add(c - 1);
1203	        } else {
1204	          newCollapsed.add(c);
1205	        }
1206	      }
1207	      collapsedColumns = newCollapsed;
1208	      renderColumns();
1209	      updateInspector();
1210	      showToast(`Deleted "${name}"`);
1211	    }
1212	
1213	    function moveColumn(idx, direction) {
1214	      if (!activeTable) return;
1215	      const table = tables[activeTable];
1216	      const targetIdx = idx + direction;
1217	      if (targetIdx < 0 || targetIdx >= table.columns.length) return;
1218	
1219	      // Swap columns
1220	      const temp = table.columns[idx];
1221	      table.columns[idx] = table.columns[targetIdx];
1222	      table.columns[targetIdx] = temp;
1223	
1224	      // Also move collapsed state
1225	      const wasCollapsed = collapsedColumns.has(idx);
1226	      const targetWasCollapsed = collapsedColumns.has(targetIdx);
1227	
1228	      if (wasCollapsed) {
1229	        collapsedColumns.delete(idx);
1230	        collapsedColumns.add(targetIdx);
1231	      }
1232	      if (targetWasCollapsed && !wasCollapsed) {
1233	        collapsedColumns.delete(targetIdx);
1234	        collapsedColumns.add(idx);
1235	      }
1236	
1237	      renderColumns();
1238	      updateInspector();
1239	    }
1240	
1241	    function updateColumnName(idx, value) {
1242	      tables[activeTable].columns[idx].name = value;
1243	      updateInspector();
1244	    }
1245	
1246	    function updateColumnType(idx, value) {
1247	      tables[activeTable].columns[idx].type = value;
1248	      tables[activeTable].columns[idx].metadata = {};
1249	      if (value.startsWith('enum_')) tables[activeTable].columns[idx].metadata.options = ['option1'];
1250	      if (value.startsWith('relation_')) tables[activeTable].columns[idx].metadata.target = 'self';
1251	      if (value === 'hex_id') tables[activeTable].columns[idx].metadata.prefix = activeTable.substring(0, 4).toUpperCase();
1252	      renderColumns();
1253	      updateInspector();
1254	    }
1255	
1256	    function updateMeta(idx, key, value) {
1257	      if (!tables[activeTable].columns[idx].metadata) tables[activeTable].columns[idx].metadata = {};
1258	      tables[activeTable].columns[idx].metadata[key] = value;
1259	      updateInspector();
1260	    }
