  draggedIndex = Number(event.target.closest('.column-token').dataset.index);
  event.target.classList.add('dragging');
  event.dataTransfer.effectAllowed = 'move';
  event.dataTransfer.setData('text/plain', draggedIndex);
}

function onDragOver(event) {
  event.preventDefault();
  event.dataTransfer.dropEffect = 'move';

  const afterElement = getDragAfterElement(event.target.closest('.dashboard-tokens'), event.clientY);
  if (afterElement == null) {
    // dragging to the end
    return;
  }

  const draggable = document.querySelector('.column-token.dragging');
  if (!draggable) return;

  const dashboard = event.target.closest('.dashboard-tokens');
  if (!dashboard) return;

  dashboard.insertBefore(draggable, afterElement);
}

function onDrop(event) {
  event.preventDefault();
  const dropIndex = Number(event.target.closest('.column-token').dataset.index);

  if (draggedIndex === null || draggedIndex === dropIndex) {
    return;
  }

  // Move the column in the data
  moveColumn(draggedIndex, dropIndex > draggedIndex ? 1 : -1);

  // Update visual order
  renderColumnOrderDashboard();

  // Update inspector
  updateInspector();
}

function onDragEnd(event) {
  event.target.classList.remove('dragging');
  draggedIndex = null;
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll('.column-token:not(.dragging)')];

  return draggableElements.reduce((closest, child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;

    if (offset < 0 && offset > closest.offset) {
      return { offset: offset, element: child };
    } else {
      return closest;
    }
  }, { offset: Number.NEGATIVE_INFINITY }).element;
}

