1100	    function createTable() {
1101	      const name = prompt('Table name (e.g., tasks, inventory):');
1102	      if (!name) return;
1103	      const clean = name.toLowerCase().replace(/[^a-z0-9_]/g, '_');
1104	      if (tables[clean]) {
1105	        alert('Table already exists');
1106	        return;
1107	      }
1108	      tables[clean] = {
1109	        table_name: clean,
1110	        columns: [{ name: 'ID', slug: 'id', type: 'hex_id', metadata: { prefix: clean.substring(0, 4).toUpperCase() } }]
1111	      };
1112	      switchTable(clean);
1113	      showToast(`Created table "${clean}"`);
1114	    }
