1120	      bar.innerHTML = categories.map(cat => `
1121	        <button class="filter-btn ${cat === activeFilter ? 'active' : ''}" onclick="setFilter('${cat}')">
1122	          ${icons[cat]} ${cat === 'all' ? 'All' : cat.charAt(0).toUpperCase() + cat.slice(1)}
1123	        </button>
1124	      `).join('');
