1133	    function renderColumns() {
1134	      if (!tables[activeTable]) return;
1135	      const table = tables[activeTable];
1136	      const stream = document.getElementById('columns-stream');
1137	
1138	      const columnCount = table.columns.length;
1139	      document.getElementById('columns-count').textContent = `${columnCount} column${columnCount !== 1 ? 's' : ''}`;
1140	
1141	      const filtered = activeFilter === 'all'
1142	        ? table.columns
1143	        : table.columns.filter(col => FIELD_TYPES[col.type]?.category === activeFilter);
1144	
1145	      if (filtered.length === 0) {
1146	        stream.innerHTML = '<div style="padding: 3rem 1.5rem; text-align: center; color: var(--text-dim);">No columns in this category</div>';
1147	        return;
1148	      }
1149	
1150	      stream.innerHTML = filtered.map((col, idx) => renderColumnCard(col, idx)).join('');
1151	
1152	      // Update the column order dashboard
1153	      renderColumnOrderDashboard();
