1156	    function renderColumnCard(col, idx) {
1157	      const type = FIELD_TYPES[col.type];
1158	      const table = tables[activeTable];
1159	      const isFirst = idx === 0;
1160	      const isLast = idx === table.columns.length - 1;
1161	
1162	      return `
1163	        <section class="card column-card ${type.category} ${collapsedColumns.has(idx) ? 'collapsed' : ''}" id="col-${idx}">
1164	          <div class="column-card-header" onclick="toggleColumnCollapse(${idx})">
1165	            <div style="display: flex; align-items: center; gap: 0.5rem; flex: 1; min-width: 0;">
1166	              <span class="column-chevron">${collapsedColumns.has(idx) ? '▶' : '▼'}</span>
1167	              <div class="column-card-title">
1168	                <span class="column-icon">${type.icon}</span>
1169	                <span class="column-number">#${idx + 1}</span>
1170	                <span class="column-name">${col.name}</span>
1171	              </div>
1172	            </div>
1173	            <div class="column-controls" onclick="event.stopPropagation()">
1174	              <div class="column-reorder">
1175	                <button class="reorder-btn" onclick="moveColumn(${idx}, -1)" ${isFirst ? 'disabled' : ''} title="Move Up">▲</button>
1176	                <button class="reorder-btn" onclick="moveColumn(${idx}, 1)" ${isLast ? 'disabled' : ''} title="Move Down">▼</button>
1177	              </div>
1178	              <span class="column-tag">${type.title}</span>
1179	              <button class="btn small icon-only" onclick="deleteColumn(${idx})" title="Delete">✕</button>
1180	            </div>
1181	          </div>
1182	          <div class="column-card-body">
1183	            <div class="field-grid-2">
1184	              <div class="field-group">
1185	                <label class="field-label">Column Name</label>
1186	                <input type="text" value="${col.name}" onchange="updateColumnName(${idx}, this.value)">
1187	              </div>
1188	              <div class="field-group">
1189	                <label class="field-label">Column Type</label>
1190	                <select onchange="updateColumnType(${idx}, this.value)">
1191	                  ${Object.entries(FIELD_TYPES).map(([slug, info]) => `
1192	                    <option value="${slug}" ${col.type === slug ? 'selected' : ''}>
1193	                      ${info.icon} ${info.title}
1194	                    </option>
1195	                  `).join('')}
1196	                </select>
1197	              </div>
1198	            </div>
1199	            ${renderMetadata(col, idx)}
1200	          </div>
1201	        </section>
1202	      `;
1203	    }
1204	
1205	    function renderMetadata(col, idx) {
1206	      const meta = col.metadata || {};
1207	      if (col.type === 'hex_id') {
1208	        return `
1209	          <div class="field-group">
1210	            <label class="field-label">ID Prefix (4 chars)</label>
1211	            <input type="text" maxlength="4" value="${meta.prefix || ''}"
1212	              onchange="updateMeta(${idx}, 'prefix', this.value)">
1213	          </div>
1214	        `;
1215	      }
1216	      if (col.type.startsWith('enum_')) {
1217	        const options = Array.isArray(meta.options) ? meta.options : [];
1218	        return `
1219	          <div class="field-group">
1220	            <label class="field-label">Options</label>
1221	            <div style="display: flex; flex-wrap: wrap; gap: 0.5rem;">
1222	              ${options.map((opt, i) => `
1223	                <span style="background: var(--accent-bg); color: var(--accent); padding: 0.4rem 0.8rem; border-radius: 4px; font-size: 13px; display: flex; gap: 0.5rem; align-items: center;">
1224	                  ${opt}
1225	                  <button onclick="removeOption(${idx}, ${i})" style="background: none; border: none; cursor: pointer; color: var(--accent); padding: 0;">✕</button>
1226	                </span>
1227	              `).join('')}
1228	            </div>
1229	            <input type="text" placeholder="Add option, press Enter"
1230	              onkeydown="if(event.key==='Enter'){addOption(${idx}, this.value); this.value='';}">
1231	          </div>
1232	        `;
1233	      }
1234	      if (col.type.startsWith('relation_')) {
1235	        const target = meta.target || 'self';
1236	        return `
1237	          <div class="field-group">
1238	            <label class="field-label">Target Table</label>
1239	            <select onchange="updateMeta(${idx}, 'target', this.value)">
1240	              <option value="self" ${target === 'self' ? 'selected' : ''}>Self (tree)</option>
1241	              ${Object.keys(tables).map(t => `
1242	                <option value="${t}" ${target === t ? 'selected' : ''}>${t}</option>
1243	              `).join('')}
1244	            </select>
1245	          </div>
1246	        `;
1247	      }
1248	      return '';
1249	    }
