1251	    function addField(type) {
1252	      const table = tables[activeTable];
1253	      const newCol = {
1254	        name: FIELD_TYPES[type].title,
1255	        slug: 'new_field',
1256	        type: type,
1257	        metadata: {}
1258	      };
1259	      if (type.startsWith('enum_')) newCol.metadata.options = ['option1', 'option2'];
1260	      if (type.startsWith('relation_')) newCol.metadata.target = 'self';
1261	      if (type === 'hex_id') newCol.metadata.prefix = activeTable.substring(0, 4).toUpperCase();
1262	      table.columns.push(newCol);
1263	      renderColumns();
1264	      updateInspector();
1265	      showToast(`Added ${FIELD_TYPES[type].title}`);
1266	    }
1267	
1268	    function deleteColumn(idx) {
1269	      const name = tables[activeTable].columns[idx].name;
1270	      tables[activeTable].columns.splice(idx, 1);
1271	      // Also remove collapsed state for this index and shift higher indices down
1272	      if (collapsedColumns.has(idx)) {
1273	        collapsedColumns.delete(idx);
1274	      }
1275	      // Shift collapsed indices > idx down by 1
1276	      const newCollapsed = new Set();
1277	      for (const c of collapsedColumns) {
1278	        if (c > idx) {
1279	          newCollapsed.add(c - 1);
1280	        } else {
1281	          newCollapsed.add(c);
1282	        }
1283	      }
1284	      collapsedColumns = newCollapsed;
1285	      renderColumns();
1286	      updateInspector();
1287	      showToast(`Deleted "${name}"`);
1288	    }
1289	
1290	    function moveColumn(idx, direction) {
1291	      if (!activeTable) return;
1292	      const table = tables[activeTable];
1293	      const targetIdx = idx + direction;
1294	      if (targetIdx < 0 || targetIdx >= table.columns.length) return;
1295	
1296	      // Swap columns
1297	      const temp = table.columns[idx];
1298	      table.columns[idx] = table.columns[targetIdx];
1299	      table.columns[targetIdx] = temp;
1300	
1301	      // Also move collapsed state
1302	      const wasCollapsed = collapsedColumns.has(idx);
1303	      const targetWasCollapsed = collapsedColumns.has(targetIdx);
1304	
1305	      if (wasCollapsed) {
1306	        collapsedColumns.delete(idx);
1307	        collapsedColumns.add(targetIdx);
1308	      }
1309	      if (targetWasCollapsed && !wasCollapsed) {
1310	        collapsedColumns.delete(targetIdx);
1311	        collapsedColumns.add(idx);
1312	      }
1313	
1314	      renderColumns();
1315	      updateInspector();
1316	    }
1317	
