1323	    function updateColumnType(idx, value) {
1324	      tables[activeTable].columns[idx].type = value;
1325	      tables[activeTable].columns[idx].metadata = {};
1326	      if (value.startsWith('enum_')) tables[activeTable].columns[idx].metadata.options = ['option1'];
1327	      if (value.startsWith('relation_')) tables[activeTable].columns[idx].metadata.target = 'self';
1328	      if (value === 'hex_id') tables[activeTable].columns[idx].metadata.prefix = activeTable.substring(0, 4).toUpperCase();
1329	      renderColumns();
1330	      updateInspector();
1331	    }
1332	
1333	    function updateMeta(idx, key, value) {
1334	      if (!tables[activeTable].columns[idx].metadata) tables[activeTable].columns[idx].metadata = {};
1335	      tables[activeTable].columns[idx].metadata[key] = value;
1336	      updateInspector();
