1339	    function addOption(idx, value) {
1340	      if (!value.trim()) return;
1341	      const meta = tables[activeTable].columns[idx].metadata;
1342	      if (!Array.isArray(meta.options)) meta.options = [];
1343	      if (!meta.options.includes(value)) meta.options.push(value);
1344	      renderColumns();
1345	      updateInspector();
1346	    }
1347	
1348	    function removeOption(idx, optIdx) {
