1361	    function generateSQL(table) {
1362	      if (!table) return '-- No table';
1363	      const lines = [`CREATE TABLE IF NOT EXISTS ${table.table_name} (`];
1364	      const cols = table.columns.map(col => {
1365	        const type = FIELD_TYPES[col.type];
1366	        return `    ${(col.slug || col.name).padEnd(20)} ${type.sql}`;
1367	      });
1368	      lines.push(cols.join(',\n'));
1369	      lines.push(');');
1370	      return lines.join('\n');
1371	    }
