1382	        titleEl.textContent = `JSON Schema (${activeTable}.json)`;
1383	        codeEl.textContent = JSON.stringify(table, null, 2);
1384	      } else {
1385	        titleEl.textContent = 'Database Status';
1386	        codeEl.textContent = JSON.stringify({
1387	          mode: 'Standalone (embedded mock data)',
1388	          tables: Object.keys(tables),
1389	          active_table: activeTable,
1390	          column_count: table.columns.length
1391	        }, null, 2);
1392	      }
1393	    }
