1428	    // Column Order Dashboard Functions
1429	    function renderColumnOrderDashboard() {
1430	      if (!tables[activeTable]) return;
1431	      const table = tables[activeTable];
1432	      const dashboard = document.getElementById('dashboard-tokens');
1433	      if (!dashboard) return;
1434	
1435	      dashboard.innerHTML = table.columns.map((col, idx) => {
1436	        const type = FIELD_TYPES[col.type];
1437	        return `
1438	          <div class="column-token" draggable="true" data-index="${idx}" ondragstart="onDragStart(event)" ondragover="onDragOver(event)" ondrop="onDrop(event)" ondragend="onDragEnd(event)">
1439	            <span class="token-icon">${type.icon}</span>
1440	            <span class="token-name">${col.name}</span>
1441	            <span class="token-type">${type.title}</span>
1442	          </div>
1443	        `;
1444	      }).join('');
1445	    }
1446	
1447	    let draggedIndex = null;
1448	
1449	    function onDragStart(event) {
1450	      draggedIndex = Number(event.target.closest('.column-token').dataset.index);
1451	      event.target.classList.add('dragging');
1452	      event.dataTransfer.effectAllowed = 'move';
1453	      event.dataTransfer.setData('text/plain', draggedIndex);
1454	    }
1455	
1456	    function onDragOver(event) {
1457	      event.preventDefault();
1458	      event.dataTransfer.dropEffect = 'move';
1459	
1460	      const afterElement = getDragAfterElement(event.target.closest('.dashboard-tokens'), event.clientY);
1461	      if (afterElement == null) {
1462	        // dragging to the end
1463	        return;
1464	      }
1465	
1466	      const draggable = document.querySelector('.column-token.dragging');
1467	      if (!draggable) return;
1468	
1469	      const dashboard = event.target.closest('.dashboard-tokens');
1470	      if (!dashboard) return;
1471	
1472	      dashboard.insertBefore(draggable, afterElement);
1473	    }
1474	
1475	    function onDrop(event) {
1476	      event.preventDefault();
1477	      const dropIndex = Number(event.target.closest('.column-token').dataset.index);
1478	
1479	      if (draggedIndex === null || draggedIndex === dropIndex) {
1480	        return;
1481	      }
1482	
1483	      // Move the column in the data
1484	      moveColumn(draggedIndex, dropIndex > draggedIndex ? 1 : -1);
1485	
1486	      // Update visual order
1487	      renderColumnOrderDashboard();
1488	
1489	      // Update inspector
1490	      updateInspector();
1491	    }
1492	
1493	    function onDragEnd(event) {
1494	      event.target.classList.remove('dragging');
1495	      draggedIndex = null;
1496	    }
1497	
1498	    function getDragAfterElement(container, y) {
1499	      const draggableElements = [...container.querySelectorAll('.column-token:not(.dragging)')];
1500	
1501	      return draggableElements.reduce((closest, child) => {
1502	        const box = child.getBoundingClientRect();
1503	        const offset = y - box.top - box.height / 2;
1504	
1505	        if (offset < 0 && offset > closest.offset) {
1506	          return { offset: offset, element: child };
1507	        } else {
1508	          return closest;
1509	        }
1510	      }, { offset: Number.NEGATIVE_INFINITY }).element;
1511	    }
1512	
